insert into public.translations (locale, key, value) values
  ('pt-BR', 'agent.approveMcps', $json$"Aprovar servidores MCP"$json$::jsonb),
  ('en', 'agent.approveMcps', $json$"Approve MCP servers"$json$::jsonb),
  ('es', 'agent.approveMcps', $json$"Aprobar servidores MCP"$json$::jsonb),
  ('zh-CN', 'agent.approveMcps', $json$"批准 MCP 服务器"$json$::jsonb),
  ('hi', 'agent.approveMcps', $json$"MCP सर्वर स्वीकृत करें"$json$::jsonb),
  ('ar', 'agent.approveMcps', $json$"الموافقة على خوادم MCP"$json$::jsonb),
  ('fr', 'agent.approveMcps', $json$"Approuver les serveurs MCP"$json$::jsonb),
  ('ru', 'agent.approveMcps', $json$"Одобрять серверы MCP"$json$::jsonb),
  ('ja', 'agent.approveMcps', $json$"MCP サーバーを承認"$json$::jsonb),
  ('de', 'agent.approveMcps', $json$"MCP-Server freigeben"$json$::jsonb),
  ('pt-BR', 'agent.approveMcps.hint.cli', $json$"Entrega a este agente os servidores da aba MCP a cada pedido e o deixa usar as ferramentas deles sem perguntar. Desligado, nenhum chega a ele."$json$::jsonb),
  ('en', 'agent.approveMcps.hint.cli', $json$"Hands this agent the servers of the MCP tab on every request and lets it use their tools without asking. Off, none of them reaches it."$json$::jsonb),
  ('es', 'agent.approveMcps.hint.cli', $json$"Entrega a este agente los servidores de la pestaña MCP en cada petición y le deja usar sus herramientas sin preguntar. Desactivado, ninguno le llega."$json$::jsonb),
  ('zh-CN', 'agent.approveMcps.hint.cli', $json$"每次请求都把 MCP 标签页中的服务器交给此代理，并允许它无需询问就使用这些服务器的工具。关闭后，任何服务器都不会送达。"$json$::jsonb),
  ('hi', 'agent.approveMcps.hint.cli', $json$"हर अनुरोध पर MCP टैब के सर्वर इस एजेंट को सौंपता है और उसे बिना पूछे उनके टूल इस्तेमाल करने देता है। बंद होने पर कोई भी सर्वर उस तक नहीं पहुँचता।"$json$::jsonb),
  ('ar', 'agent.approveMcps.hint.cli', $json$"يسلّم هذا الوكيل خوادم تبويب MCP مع كل طلب ويتيح له استخدام أدواتها دون سؤال. عند الإيقاف لا يصله أي منها."$json$::jsonb),
  ('fr', 'agent.approveMcps.hint.cli', $json$"Remet à cet agent les serveurs de l’onglet MCP à chaque requête et le laisse utiliser leurs outils sans demander. Désactivé, aucun ne lui parvient."$json$::jsonb),
  ('ru', 'agent.approveMcps.hint.cli', $json$"Передаёт этому агенту серверы со вкладки MCP при каждом запросе и разрешает использовать их инструменты без вопросов. Если выключено, ни один сервер до него не доходит."$json$::jsonb),
  ('ja', 'agent.approveMcps.hint.cli', $json$"リクエストのたびに、MCP タブのサーバーをこのエージェントに渡し、確認なしでそのツールを使えるようにします。オフの間は、どのサーバーも届きません。"$json$::jsonb),
  ('de', 'agent.approveMcps.hint.cli', $json$"Übergibt diesem Agenten bei jeder Anfrage die Server des MCP-Tabs und lässt ihn deren Werkzeuge ohne Rückfrage nutzen. Ausgeschaltet erreicht ihn keiner."$json$::jsonb),
  ('pt-BR', 'agent.approveMcps.hint.cursor', $json$"Grava os servidores da aba MCP no ~/.cursor/mcp.json do Cursor (só os que o JayV adicionou; o resto do arquivo fica como está) e deixa o agente usar todos os servidores MCP sem perguntar."$json$::jsonb),
  ('en', 'agent.approveMcps.hint.cursor', $json$"Writes the servers of the MCP tab to Cursor’s ~/.cursor/mcp.json (only the ones JayV added, the rest of the file stays as it is) and lets the agent use every MCP server without asking."$json$::jsonb),
  ('es', 'agent.approveMcps.hint.cursor', $json$"Escribe los servidores de la pestaña MCP en el ~/.cursor/mcp.json de Cursor (solo los que añadió JayV; el resto del archivo queda como está) y deja que el agente use todos los servidores MCP sin preguntar."$json$::jsonb),
  ('zh-CN', 'agent.approveMcps.hint.cursor', $json$"把 MCP 标签页中的服务器写入 Cursor 的 ~/.cursor/mcp.json（只写 JayV 添加的，文件其余部分保持不变），并让代理无需询问就使用所有 MCP 服务器。"$json$::jsonb),
  ('hi', 'agent.approveMcps.hint.cursor', $json$"MCP टैब के सर्वर Cursor की ~/.cursor/mcp.json में लिखता है (सिर्फ़ वही जो JayV ने जोड़े; फ़ाइल का बाकी हिस्सा जैसा है वैसा रहता है) और एजेंट को सभी MCP सर्वर बिना पूछे इस्तेमाल करने देता है।"$json$::jsonb),
  ('ar', 'agent.approveMcps.hint.cursor', $json$"يكتب خوادم تبويب MCP في ملف ‎~/.cursor/mcp.json‎ الخاص بـ Cursor (التي أضافها JayV فقط، ويبقى باقي الملف كما هو) ويتيح للوكيل استخدام كل خوادم MCP دون سؤال."$json$::jsonb),
  ('fr', 'agent.approveMcps.hint.cursor', $json$"Écrit les serveurs de l’onglet MCP dans le ~/.cursor/mcp.json de Cursor (seulement ceux ajoutés par JayV, le reste du fichier reste tel quel) et laisse l’agent utiliser tous les serveurs MCP sans demander."$json$::jsonb),
  ('ru', 'agent.approveMcps.hint.cursor', $json$"Записывает серверы со вкладки MCP в ~/.cursor/mcp.json Cursor (только те, что добавил JayV, остальная часть файла не меняется) и разрешает агенту использовать все серверы MCP без вопросов."$json$::jsonb),
  ('ja', 'agent.approveMcps.hint.cursor', $json$"MCP タブのサーバーを Cursor の ~/.cursor/mcp.json に書き込み（JayV が追加したものだけで、ファイルのほかの部分はそのまま）、エージェントがすべての MCP サーバーを確認なしで使えるようにします。"$json$::jsonb),
  ('de', 'agent.approveMcps.hint.cursor', $json$"Schreibt die Server des MCP-Tabs in die ~/.cursor/mcp.json von Cursor (nur die von JayV hinzugefügten, der Rest der Datei bleibt unverändert) und lässt den Agenten alle MCP-Server ohne Rückfrage nutzen."$json$::jsonb),
  ('pt-BR', 'agent.approveMcps.hint.gateway', $json$"O JayV sobe os servidores da aba MCP por conta própria, oferece as ferramentas deles ao modelo e executa as chamadas que ele pedir, sem perguntar. Desligado, o gateway responde só por texto."$json$::jsonb),
  ('en', 'agent.approveMcps.hint.gateway', $json$"JayV starts the servers of the MCP tab itself, offers their tools to the model and runs the calls it asks for, without asking. Off, the gateway answers with text only."$json$::jsonb),
  ('es', 'agent.approveMcps.hint.gateway', $json$"JayV inicia por su cuenta los servidores de la pestaña MCP, ofrece sus herramientas al modelo y ejecuta las llamadas que pida, sin preguntar. Desactivado, el gateway responde solo con texto."$json$::jsonb),
  ('zh-CN', 'agent.approveMcps.hint.gateway', $json$"JayV 自己启动 MCP 标签页中的服务器，把它们的工具提供给模型，并在模型请求时直接执行调用，无需询问。关闭后，网关只回复文本。"$json$::jsonb),
  ('hi', 'agent.approveMcps.hint.gateway', $json$"JayV MCP टैब के सर्वर खुद चालू करता है, उनके टूल मॉडल को देता है और मॉडल जो कॉल माँगे उन्हें बिना पूछे चलाता है। बंद होने पर गेटवे सिर्फ़ टेक्स्ट में जवाब देता है।"$json$::jsonb),
  ('ar', 'agent.approveMcps.hint.gateway', $json$"يشغّل JayV خوادم تبويب MCP بنفسه ويعرض أدواتها على النموذج وينفّذ الاستدعاءات التي يطلبها دون سؤال. عند الإيقاف يجيب البوابة بالنص فقط."$json$::jsonb),
  ('fr', 'agent.approveMcps.hint.gateway', $json$"JayV lance lui-même les serveurs de l’onglet MCP, propose leurs outils au modèle et exécute les appels qu’il demande, sans demander. Désactivé, la passerelle répond uniquement par du texte."$json$::jsonb),
  ('ru', 'agent.approveMcps.hint.gateway', $json$"JayV сам запускает серверы со вкладки MCP, предлагает их инструменты модели и выполняет запрошенные ею вызовы без вопросов. Если выключено, шлюз отвечает только текстом."$json$::jsonb),
  ('ja', 'agent.approveMcps.hint.gateway', $json$"JayV が MCP タブのサーバーを自分で起動し、そのツールをモデルに提示して、モデルが求める呼び出しを確認なしで実行します。オフの間、ゲートウェイはテキストでのみ応答します。"$json$::jsonb),
  ('de', 'agent.approveMcps.hint.gateway', $json$"JayV startet die Server des MCP-Tabs selbst, bietet dem Modell deren Werkzeuge an und führt die angeforderten Aufrufe ohne Rückfrage aus. Ausgeschaltet antwortet das Gateway nur mit Text."$json$::jsonb),
  ('pt-BR', 'palette.mcpApprove', $json$"Aprovar servidores MCP: {name}"$json$::jsonb),
  ('en', 'palette.mcpApprove', $json$"Approve MCP servers: {name}"$json$::jsonb),
  ('es', 'palette.mcpApprove', $json$"Aprobar servidores MCP: {name}"$json$::jsonb),
  ('zh-CN', 'palette.mcpApprove', $json$"批准 MCP 服务器：{name}"$json$::jsonb),
  ('hi', 'palette.mcpApprove', $json$"MCP सर्वर स्वीकृत करें: {name}"$json$::jsonb),
  ('ar', 'palette.mcpApprove', $json$"الموافقة على خوادم MCP: {name}"$json$::jsonb),
  ('fr', 'palette.mcpApprove', $json$"Approuver les serveurs MCP : {name}"$json$::jsonb),
  ('ru', 'palette.mcpApprove', $json$"Одобрять серверы MCP: {name}"$json$::jsonb),
  ('ja', 'palette.mcpApprove', $json$"MCP サーバーを承認: {name}"$json$::jsonb),
  ('de', 'palette.mcpApprove', $json$"MCP-Server freigeben: {name}"$json$::jsonb),
  ('pt-BR', 'palette.mcpRevoke', $json$"Parar de aprovar servidores MCP: {name}"$json$::jsonb),
  ('en', 'palette.mcpRevoke', $json$"Stop approving MCP servers: {name}"$json$::jsonb),
  ('es', 'palette.mcpRevoke', $json$"Dejar de aprobar servidores MCP: {name}"$json$::jsonb),
  ('zh-CN', 'palette.mcpRevoke', $json$"停止批准 MCP 服务器：{name}"$json$::jsonb),
  ('hi', 'palette.mcpRevoke', $json$"MCP सर्वर स्वीकृत करना बंद करें: {name}"$json$::jsonb),
  ('ar', 'palette.mcpRevoke', $json$"إيقاف الموافقة على خوادم MCP: {name}"$json$::jsonb),
  ('fr', 'palette.mcpRevoke', $json$"Ne plus approuver les serveurs MCP : {name}"$json$::jsonb),
  ('ru', 'palette.mcpRevoke', $json$"Не одобрять серверы MCP: {name}"$json$::jsonb),
  ('ja', 'palette.mcpRevoke', $json$"MCP サーバーの承認を停止: {name}"$json$::jsonb),
  ('de', 'palette.mcpRevoke', $json$"MCP-Server nicht mehr freigeben: {name}"$json$::jsonb),
  ('pt-BR', 'mcp.cursorFile', $json$"O arquivo MCP do Cursor não é um JSON válido, então o JayV não mexeu nele: {path}"$json$::jsonb),
  ('en', 'mcp.cursorFile', $json$"Cursor’s MCP file is not valid JSON, so JayV left it alone: {path}"$json$::jsonb),
  ('es', 'mcp.cursorFile', $json$"El archivo MCP de Cursor no es un JSON válido, así que JayV no lo tocó: {path}"$json$::jsonb),
  ('zh-CN', 'mcp.cursorFile', $json$"Cursor 的 MCP 文件不是有效的 JSON，因此 JayV 没有改动它：{path}"$json$::jsonb),
  ('hi', 'mcp.cursorFile', $json$"Cursor की MCP फ़ाइल मान्य JSON नहीं है, इसलिए JayV ने उसे नहीं छुआ: {path}"$json$::jsonb),
  ('ar', 'mcp.cursorFile', $json$"ملف MCP الخاص بـ Cursor ليس JSON صالحًا، لذا لم يعدّله JayV: {path}"$json$::jsonb),
  ('fr', 'mcp.cursorFile', $json$"Le fichier MCP de Cursor n’est pas un JSON valide, JayV n’y a donc pas touché : {path}"$json$::jsonb),
  ('ru', 'mcp.cursorFile', $json$"Файл MCP у Cursor — не корректный JSON, поэтому JayV его не трогал: {path}"$json$::jsonb),
  ('ja', 'mcp.cursorFile', $json$"Cursor の MCP ファイルが有効な JSON ではないため、JayV は変更しませんでした: {path}"$json$::jsonb),
  ('de', 'mcp.cursorFile', $json$"Die MCP-Datei von Cursor ist kein gültiges JSON, daher hat JayV sie unverändert gelassen: {path}"$json$::jsonb),
  ('pt-BR', 'mcp.description', $json$"Servidores que o JayV entrega a todos os agentes em cada pedido, quando o “Aprovar servidores MCP” está ligado na aba do agente. As ferramentas deles rodam sem perguntar, porque ninguém consegue aprovar enquanto o agente trabalha."$json$::jsonb),
  ('en', 'mcp.description', $json$"Servers JayV hands to every agent on each request, once “Approve MCP servers” is on in that agent’s tab. Their tools run without asking, because nobody can approve them while the agent works."$json$::jsonb),
  ('es', 'mcp.description', $json$"Servidores que JayV entrega a todos los agentes en cada petición, cuando «Aprobar servidores MCP» está activado en la pestaña del agente. Sus herramientas se ejecutan sin preguntar, porque nadie puede aprobarlas mientras el agente trabaja."$json$::jsonb),
  ('zh-CN', 'mcp.description', $json$"当代理标签页中的“批准 MCP 服务器”开启时，JayV 在每次请求中把这些服务器交给所有代理。它们的工具无需询问直接运行，因为代理工作时没有人能批准。"$json$::jsonb),
  ('hi', 'mcp.description', $json$"जब एजेंट के टैब में “MCP सर्वर स्वीकृत करें” चालू हो, तो JayV हर अनुरोध पर ये सर्वर सभी एजेंटों को सौंपता है। उनके टूल बिना पूछे चलते हैं, क्योंकि एजेंट के काम करते समय कोई उन्हें स्वीकृत नहीं कर सकता।"$json$::jsonb),
  ('ar', 'mcp.description', $json$"خوادم يسلّمها JayV إلى كل الوكلاء مع كل طلب عندما يكون خيار «الموافقة على خوادم MCP» مفعّلًا في تبويب الوكيل. تعمل أدواتها دون سؤال لأن أحدًا لا يستطيع الموافقة عليها أثناء عمل الوكيل."$json$::jsonb),
  ('fr', 'mcp.description', $json$"Serveurs que JayV remet à tous les agents à chaque requête, lorsque « Approuver les serveurs MCP » est activé dans l’onglet de l’agent. Leurs outils s’exécutent sans demander, car personne ne peut les approuver pendant que l’agent travaille."$json$::jsonb),
  ('ru', 'mcp.description', $json$"Серверы, которые JayV передаёт всем агентам при каждом запросе, если на вкладке агента включено «Одобрять серверы MCP». Их инструменты работают без вопросов, потому что пока агент работает, одобрить их некому."$json$::jsonb),
  ('ja', 'mcp.description', $json$"エージェントのタブで「MCP サーバーを承認」がオンのとき、JayV がリクエストのたびにすべてのエージェントへ渡すサーバーです。エージェントの作業中は誰も承認できないため、ツールは確認なしで実行されます。"$json$::jsonb),
  ('de', 'mcp.description', $json$"Server, die JayV bei jeder Anfrage an alle Agenten übergibt, sobald „MCP-Server freigeben“ im Tab des Agenten eingeschaltet ist. Ihre Werkzeuge laufen ohne Rückfrage, weil sie niemand freigeben kann, während der Agent arbeitet."$json$::jsonb),
  ('pt-BR', 'mcp.notes', $json$"Claude Code, Codex e Copilot os recebem na linha de comando, o Kilo Code na configuração em linha, o Cursor por um bloco que o JayV mantém no ~/.cursor/mcp.json, e o OpenRouter e o LiteLLM pelo próprio JayV, que chama as ferramentas para o modelo. O modo planejamento e as políticas de organização com agentes seguros rodam sem estes servidores. As variáveis de ambiente ficam neste computador."$json$::jsonb),
  ('en', 'mcp.notes', $json$"Claude Code, Codex and Copilot receive them on the command line, Kilo Code in its inline configuration, Cursor through a block JayV keeps in ~/.cursor/mcp.json, and OpenRouter and LiteLLM through JayV itself, which calls the tools for the model. Planning mode and organization policies with safe agents run without these servers. Environment variables stay on this computer."$json$::jsonb),
  ('es', 'mcp.notes', $json$"Claude Code, Codex y Copilot los reciben por la línea de comandos, Kilo Code en su configuración en línea, Cursor mediante un bloque que JayV mantiene en ~/.cursor/mcp.json, y OpenRouter y LiteLLM a través del propio JayV, que llama a las herramientas por el modelo. El modo de planificación y las políticas de organización con agentes seguros funcionan sin estos servidores. Las variables de entorno se quedan en este equipo."$json$::jsonb),
  ('zh-CN', 'mcp.notes', $json$"Claude Code、Codex 和 Copilot 通过命令行接收，Kilo Code 通过内联配置接收，Cursor 通过 JayV 在 ~/.cursor/mcp.json 中维护的一段配置接收，OpenRouter 和 LiteLLM 则由 JayV 自己为模型调用工具。规划模式以及启用安全代理的组织策略不会使用这些服务器。环境变量只保留在这台电脑上。"$json$::jsonb),
  ('hi', 'mcp.notes', $json$"Claude Code, Codex और Copilot इन्हें कमांड लाइन पर पाते हैं, Kilo Code इनलाइन कॉन्फ़िगरेशन में, Cursor ~/.cursor/mcp.json में JayV के रखे एक ब्लॉक से, और OpenRouter व LiteLLM खुद JayV से, जो मॉडल के लिए टूल कॉल करता है। योजना मोड और सुरक्षित एजेंट वाली संगठन नीतियाँ इन सर्वरों के बिना चलती हैं। एनवायरनमेंट वेरिएबल इसी कंप्यूटर पर रहते हैं।"$json$::jsonb),
  ('ar', 'mcp.notes', $json$"يتلقاها Claude Code وCodex وCopilot عبر سطر الأوامر، وKilo Code عبر الإعداد المضمَّن، وCursor عبر كتلة يحتفظ بها JayV في ‎~/.cursor/mcp.json‎، وOpenRouter وLiteLLM عبر JayV نفسه الذي يستدعي الأدوات نيابةً عن النموذج. يعمل وضع التخطيط وسياسات المؤسسة ذات الوكلاء الآمنين دون هذه الخوادم. تبقى متغيرات البيئة على هذا الحاسوب."$json$::jsonb),
  ('fr', 'mcp.notes', $json$"Claude Code, Codex et Copilot les reçoivent en ligne de commande, Kilo Code dans sa configuration en ligne, Cursor par un bloc que JayV tient à jour dans ~/.cursor/mcp.json, et OpenRouter et LiteLLM par JayV lui-même, qui appelle les outils pour le modèle. Le mode planification et les politiques d’organisation avec agents sûrs fonctionnent sans ces serveurs. Les variables d’environnement restent sur cet ordinateur."$json$::jsonb),
  ('ru', 'mcp.notes', $json$"Claude Code, Codex и Copilot получают их в командной строке, Kilo Code — во встроенной конфигурации, Cursor — через блок, который JayV ведёт в ~/.cursor/mcp.json, а OpenRouter и LiteLLM — через сам JayV, который вызывает инструменты за модель. Режим планирования и политики организации с безопасными агентами работают без этих серверов. Переменные окружения остаются на этом компьютере."$json$::jsonb),
  ('ja', 'mcp.notes', $json$"Claude Code・Codex・Copilot はコマンドラインで、Kilo Code はインライン設定で、Cursor は JayV が ~/.cursor/mcp.json に保つブロックで受け取ります。OpenRouter と LiteLLM は JayV 自身がモデルの代わりにツールを呼び出します。計画モードと、安全なエージェントを指定した組織ポリシーでは、これらのサーバーなしで動きます。環境変数はこのコンピューターに残ります。"$json$::jsonb),
  ('de', 'mcp.notes', $json$"Claude Code, Codex und Copilot erhalten sie auf der Kommandozeile, Kilo Code in seiner Inline-Konfiguration, Cursor über einen Block, den JayV in ~/.cursor/mcp.json pflegt, und OpenRouter und LiteLLM über JayV selbst, das die Werkzeuge für das Modell aufruft. Der Planungsmodus und Organisationsrichtlinien mit sicheren Agenten laufen ohne diese Server. Umgebungsvariablen bleiben auf diesem Computer."$json$::jsonb),
  ('pt-BR', 'gateway.textOnly', $json$"Este gateway nunca edita arquivos nem roda comandos: responde por texto, mais as ferramentas dos seus servidores MCP quando “Aprovar servidores MCP” está ligado. O Jev o usa para perguntas, análise, revisão e planejamento."$json$::jsonb),
  ('en', 'gateway.textOnly', $json$"This gateway never edits files or runs commands: it answers with text, plus the tools of your MCP servers when Approve MCP servers is on. Jev uses it for questions, analysis, review and planning."$json$::jsonb),
  ('es', 'gateway.textOnly', $json$"Este gateway nunca edita archivos ni ejecuta comandos: responde con texto, más las herramientas de tus servidores MCP cuando «Aprobar servidores MCP» está activado. Jev lo usa para preguntas, análisis, revisión y planificación."$json$::jsonb),
  ('zh-CN', 'gateway.textOnly', $json$"此网关从不编辑文件或运行命令：它只回复文本，并在“批准 MCP 服务器”开启时使用你的 MCP 服务器提供的工具。Jev 用它处理提问、分析、审查和规划。"$json$::jsonb),
  ('hi', 'gateway.textOnly', $json$"यह गेटवे कभी फ़ाइलें नहीं बदलता और कमांड नहीं चलाता: यह टेक्स्ट में जवाब देता है, और “MCP सर्वर स्वीकृत करें” चालू होने पर आपके MCP सर्वरों के टूल भी इस्तेमाल करता है। Jev इसे प्रश्नों, विश्लेषण, समीक्षा और योजना के लिए इस्तेमाल करता है।"$json$::jsonb),
  ('ar', 'gateway.textOnly', $json$"لا تعدّل هذه البوابة الملفات ولا تشغّل الأوامر أبدًا: تجيب بالنص، إضافةً إلى أدوات خوادم MCP لديك عندما يكون «الموافقة على خوادم MCP» مفعّلًا. يستخدمها Jev للأسئلة والتحليل والمراجعة والتخطيط."$json$::jsonb),
  ('fr', 'gateway.textOnly', $json$"Cette passerelle ne modifie jamais de fichiers et n’exécute jamais de commandes : elle répond par du texte, plus les outils de vos serveurs MCP lorsque « Approuver les serveurs MCP » est activé. Jev l’utilise pour les questions, l’analyse, la revue et la planification."$json$::jsonb),
  ('ru', 'gateway.textOnly', $json$"Этот шлюз никогда не редактирует файлы и не запускает команды: он отвечает текстом и, если включено «Одобрять серверы MCP», использует инструменты ваших серверов MCP. Jev применяет его для вопросов, анализа, ревью и планирования."$json$::jsonb),
  ('ja', 'gateway.textOnly', $json$"このゲートウェイはファイルの編集もコマンドの実行も行いません。テキストで応答し、「MCP サーバーを承認」がオンのときは MCP サーバーのツールも使います。Jev は質問、分析、レビュー、計画に使います。"$json$::jsonb),
  ('de', 'gateway.textOnly', $json$"Dieses Gateway bearbeitet nie Dateien und führt nie Befehle aus: Es antwortet mit Text, plus den Werkzeugen Ihrer MCP-Server, wenn „MCP-Server freigeben“ eingeschaltet ist. Jev nutzt es für Fragen, Analyse, Review und Planung."$json$::jsonb),
  ('pt-BR', 'docs.mcp.summary', $json$"Dê ferramentas extras a todos os agentes (Claude Code, Codex, Copilot, Cursor, Kilo Code, OpenRouter e LiteLLM) cadastrando servidores MCP. Um interruptor por agente, Aprovar servidores MCP, decide quem os recebe; o JayV entrega os servidores a cada pedido, a cada agente do jeito que ele entende. OpenRouter e LiteLLM não têm ferramentas próprias, então o JayV chama as ferramentas MCP por eles."$json$::jsonb),
  ('en', 'docs.mcp.summary', $json$"Give every agent (Claude Code, Codex, Copilot, Cursor, Kilo Code, OpenRouter and LiteLLM) extra tools by registering MCP servers. One switch per agent, Approve MCP servers, decides who receives them; JayV hands the servers over on every request, each agent in the way it understands. OpenRouter and LiteLLM have no tools of their own, so JayV calls the MCP tools for them."$json$::jsonb),
  ('es', 'docs.mcp.summary', $json$"Da herramientas extra a todos los agentes (Claude Code, Codex, Copilot, Cursor, Kilo Code, OpenRouter y LiteLLM) registrando servidores MCP. Un interruptor por agente, Aprobar servidores MCP, decide quién los recibe; JayV entrega los servidores en cada petición, a cada agente de la forma que entiende. OpenRouter y LiteLLM no tienen herramientas propias, así que JayV llama a las herramientas MCP por ellos."$json$::jsonb),
  ('zh-CN', 'docs.mcp.summary', $json$"通过注册 MCP 服务器，为所有代理（Claude Code、Codex、Copilot、Cursor、Kilo Code、OpenRouter 和 LiteLLM）提供额外工具。每个代理有一个“批准 MCP 服务器”开关，决定谁能收到这些服务器；JayV 在每次请求时按各代理能理解的方式交付。OpenRouter 和 LiteLLM 没有自己的工具，所以由 JayV 替它们调用 MCP 工具。"$json$::jsonb),
  ('hi', 'docs.mcp.summary', $json$"MCP सर्वर पंजीकृत करके सभी एजेंटों (Claude Code, Codex, Copilot, Cursor, Kilo Code, OpenRouter और LiteLLM) को अतिरिक्त टूल दें। हर एजेंट के लिए एक स्विच, MCP सर्वर स्वीकृत करें, तय करता है कि उन्हें कौन पाएगा; JayV हर अनुरोध पर सर्वर सौंपता है, हर एजेंट को उसी तरीके से जो वह समझता है। OpenRouter और LiteLLM के अपने टूल नहीं होते, इसलिए JayV उनकी ओर से MCP टूल कॉल करता है।"$json$::jsonb),
  ('ar', 'docs.mcp.summary', $json$"امنح كل الوكلاء (Claude Code وCodex وCopilot وCursor وKilo Code وOpenRouter وLiteLLM) أدوات إضافية بتسجيل خوادم MCP. مفتاح واحد لكل وكيل، الموافقة على خوادم MCP، يحدد من يتلقاها؛ ويسلّم JayV الخوادم مع كل طلب، لكل وكيل بالطريقة التي يفهمها. لا تملك OpenRouter وLiteLLM أدوات خاصة بهما، لذلك يستدعي JayV أدوات MCP نيابةً عنهما."$json$::jsonb),
  ('fr', 'docs.mcp.summary', $json$"Donnez des outils supplémentaires à tous les agents (Claude Code, Codex, Copilot, Cursor, Kilo Code, OpenRouter et LiteLLM) en enregistrant des serveurs MCP. Un interrupteur par agent, Approuver les serveurs MCP, décide qui les reçoit ; JayV remet les serveurs à chaque requête, à chaque agent de la façon qu’il comprend. OpenRouter et LiteLLM n’ont pas d’outils propres, JayV appelle donc les outils MCP à leur place."$json$::jsonb),
  ('ru', 'docs.mcp.summary', $json$"Дайте всем агентам (Claude Code, Codex, Copilot, Cursor, Kilo Code, OpenRouter и LiteLLM) дополнительные инструменты, зарегистрировав серверы MCP. Один переключатель на агента, «Одобрять серверы MCP», решает, кто их получает; JayV передаёт серверы при каждом запросе, каждому агенту так, как тот понимает. У OpenRouter и LiteLLM нет своих инструментов, поэтому инструменты MCP за них вызывает JayV."$json$::jsonb),
  ('ja', 'docs.mcp.summary', $json$"MCP サーバーを登録して、すべてのエージェント（Claude Code、Codex、Copilot、Cursor、Kilo Code、OpenRouter、LiteLLM）に追加ツールを与えます。エージェントごとの「MCP サーバーを承認」スイッチが受け取る相手を決め、JayV はリクエストのたびに、各エージェントが理解できる形でサーバーを渡します。OpenRouter と LiteLLM には独自のツールがないため、JayV が代わりに MCP ツールを呼び出します。"$json$::jsonb),
  ('de', 'docs.mcp.summary', $json$"Geben Sie allen Agenten (Claude Code, Codex, Copilot, Cursor, Kilo Code, OpenRouter und LiteLLM) zusätzliche Werkzeuge, indem Sie MCP-Server registrieren. Ein Schalter pro Agent, MCP-Server freigeben, entscheidet, wer sie erhält; JayV übergibt die Server bei jeder Anfrage, jedem Agenten so, wie er sie versteht. OpenRouter und LiteLLM haben keine eigenen Werkzeuge, daher ruft JayV die MCP-Werkzeuge für sie auf."$json$::jsonb),
  ('pt-BR', 'docs.mcp.usage', $json$"Abra Configurações › MCP (ou Ctrl+K › Configurações › MCP) e adicione um servidor pelo formulário ou cole uma configuração (JSON mcpServers, uma linha claude mcp add ou um comando npx). No chat, digite /mcp seguido de uma configuração ou de uma descrição: um agente monta o rascunho e nada é salvo antes de você conferir. Os servidores das suas organizações aparecem abaixo dos seus e não se editam ali. Depois ligue Aprovar servidores MCP na aba de cada agente que deve usá-los (começa desligado); Ctrl+K › Aprovar servidores MCP faz o mesmo para um agente. As organizações podem bloquear por agente, e o modo planejamento nunca leva os servidores."$json$::jsonb),
  ('en', 'docs.mcp.usage', $json$"Open Settings › MCP (or Ctrl+K › Settings › MCP) and add a server by form, or paste a configuration (mcpServers JSON, a claude mcp add line or an npx command). In a chat, type /mcp followed by a configuration or a description: an agent drafts the configuration and nothing is saved until you review it. Servers from your organizations are listed below yours and cannot be edited there. Then turn on Approve MCP servers in the Settings tab of each agent that should use them (it starts off); Ctrl+K › Approve MCP servers does the same for one agent. Organizations can block it per agent, and planning mode never carries the servers."$json$::jsonb),
  ('es', 'docs.mcp.usage', $json$"Abre Configuración › MCP (o Ctrl+K › Configuración › MCP) y añade un servidor con el formulario o pega una configuración (JSON mcpServers, una línea claude mcp add o un comando npx). En un chat, escribe /mcp seguido de una configuración o una descripción: un agente prepara el borrador y no se guarda nada hasta que lo revises. Los servidores de tus organizaciones aparecen debajo de los tuyos y no se editan allí. Después activa Aprobar servidores MCP en la pestaña de cada agente que deba usarlos (empieza desactivado); Ctrl+K › Aprobar servidores MCP hace lo mismo para un agente. Las organizaciones pueden bloquearlo por agente, y el modo de planificación nunca lleva los servidores."$json$::jsonb),
  ('zh-CN', 'docs.mcp.usage', $json$"打开“设置 › MCP”（或 Ctrl+K › 设置 › MCP），通过表单添加服务器，或粘贴配置（mcpServers JSON、claude mcp add 命令行或 npx 命令）。在聊天中输入 /mcp，后面跟配置或描述：代理会生成草稿，你确认之前不会保存任何内容。你所在组织的服务器显示在你自己的下方，不能在那里编辑。然后在每个要使用它们的代理的设置标签页中开启“批准 MCP 服务器”（默认关闭）；Ctrl+K › 批准 MCP 服务器可对单个代理执行同样的操作。组织可以按代理屏蔽它，规划模式永远不会带上这些服务器。"$json$::jsonb),
  ('hi', 'docs.mcp.usage', $json$"सेटिंग › MCP खोलें (या Ctrl+K › सेटिंग › MCP) और फ़ॉर्म से सर्वर जोड़ें या कॉन्फ़िगरेशन चिपकाएँ (mcpServers JSON, claude mcp add पंक्ति या npx कमांड)। चैट में /mcp के बाद कॉन्फ़िगरेशन या विवरण लिखें: एजेंट मसौदा बनाता है और आपके जाँचने से पहले कुछ भी सहेजा नहीं जाता। आपके संगठनों के सर्वर आपके सर्वरों के नीचे दिखते हैं और वहाँ संपादित नहीं होते। फिर हर उस एजेंट के सेटिंग टैब में MCP सर्वर स्वीकृत करें चालू करें जिसे इन्हें इस्तेमाल करना है (यह बंद से शुरू होता है); Ctrl+K › MCP सर्वर स्वीकृत करें एक एजेंट के लिए यही करता है। संगठन इसे हर एजेंट के लिए अवरुद्ध कर सकते हैं, और योजना मोड कभी सर्वर नहीं ले जाता।"$json$::jsonb),
  ('ar', 'docs.mcp.usage', $json$"افتح الإعدادات › MCP (أو Ctrl+K › الإعدادات › MCP) وأضف خادمًا بالنموذج أو الصق إعدادًا (JSON من mcpServers أو سطر claude mcp add أو أمر npx). في المحادثة اكتب ‎/mcp‎ متبوعًا بإعداد أو وصف: يُعدّ الوكيل مسودة ولا يُحفظ شيء قبل أن تراجعه. تظهر خوادم مؤسساتك أسفل خوادمك ولا تُعدَّل هناك. ثم فعّل «الموافقة على خوادم MCP» في تبويب كل وكيل يجب أن يستخدمها (يبدأ متوقفًا)؛ وCtrl+K › الموافقة على خوادم MCP يفعل الشيء نفسه لوكيل واحد. يمكن للمؤسسات حجبه لكل وكيل، ولا يحمل وضع التخطيط الخوادم أبدًا."$json$::jsonb),
  ('fr', 'docs.mcp.usage', $json$"Ouvrez Paramètres › MCP (ou Ctrl+K › Paramètres › MCP) et ajoutez un serveur par le formulaire ou collez une configuration (JSON mcpServers, une ligne claude mcp add ou une commande npx). Dans un chat, tapez /mcp suivi d’une configuration ou d’une description : un agent prépare le brouillon et rien n’est enregistré avant votre vérification. Les serveurs de vos organisations apparaissent sous les vôtres et ne s’y modifient pas. Activez ensuite Approuver les serveurs MCP dans l’onglet de chaque agent qui doit les utiliser (désactivé au départ) ; Ctrl+K › Approuver les serveurs MCP fait de même pour un agent. Les organisations peuvent le bloquer par agent, et le mode planification ne transporte jamais les serveurs."$json$::jsonb),
  ('ru', 'docs.mcp.usage', $json$"Откройте «Настройки › MCP» (или Ctrl+K › Настройки › MCP) и добавьте сервер через форму либо вставьте конфигурацию (JSON mcpServers, строку claude mcp add или команду npx). В чате введите /mcp, а затем конфигурацию или описание: агент подготовит черновик, и ничего не сохранится, пока вы его не проверите. Серверы ваших организаций показаны под вашими и там не редактируются. Затем включите «Одобрять серверы MCP» на вкладке каждого агента, который должен их использовать (по умолчанию выключено); Ctrl+K › Одобрять серверы MCP делает то же для одного агента. Организации могут блокировать это по агентам, а режим планирования никогда не берёт серверы."$json$::jsonb),
  ('ja', 'docs.mcp.usage', $json$"設定 › MCP（または Ctrl+K › 設定 › MCP）を開き、フォームでサーバーを追加するか、設定（mcpServers の JSON、claude mcp add の行、npx コマンド）を貼り付けます。チャットでは /mcp に続けて設定または説明を入力します。エージェントが下書きを作り、確認するまで何も保存されません。所属組織のサーバーは自分のものの下に表示され、そこでは編集できません。そのあと、使わせたい各エージェントの設定タブで「MCP サーバーを承認」をオンにします（初期値はオフ）。Ctrl+K › MCP サーバーを承認 で1つのエージェントに対して同じことができます。組織はエージェントごとにブロックでき、計画モードではサーバーは渡されません。"$json$::jsonb),
  ('de', 'docs.mcp.usage', $json$"Öffnen Sie Einstellungen › MCP (oder Strg+K › Einstellungen › MCP) und fügen Sie einen Server über das Formular hinzu oder fügen Sie eine Konfiguration ein (mcpServers-JSON, eine claude-mcp-add-Zeile oder einen npx-Befehl). Geben Sie im Chat /mcp gefolgt von einer Konfiguration oder Beschreibung ein: Ein Agent erstellt den Entwurf, und nichts wird gespeichert, bevor Sie ihn geprüft haben. Die Server Ihrer Organisationen stehen unter Ihren eigenen und lassen sich dort nicht bearbeiten. Schalten Sie danach „MCP-Server freigeben“ im Einstellungs-Tab jedes Agenten ein, der sie nutzen soll (standardmäßig aus); Strg+K › MCP-Server freigeben macht dasselbe für einen Agenten. Organisationen können es je Agent sperren, und der Planungsmodus trägt die Server nie."$json$::jsonb),
  ('pt-BR', 'docs.gatewayProviders.summary', $json$"Dois gateways de API dão ao Jev acesso a muitos modelos por um só endereço e uma só chave. Respondem por texto: nunca editam arquivos nem rodam comandos, então o Jev os usa para perguntas, análise, revisão e planejamento. Com Aprovar servidores MCP ligado na aba deles, o JayV também lhes oferece as ferramentas dos seus servidores MCP e executa as chamadas que pedirem."$json$::jsonb),
  ('en', 'docs.gatewayProviders.summary', $json$"Two API gateways give Jev access to many models through one address and key. They answer with text: they never edit files or run commands, so Jev uses them for questions, analysis, review and planning. With Approve MCP servers on in their tab, JayV also offers them the tools of your MCP servers and runs the calls they ask for."$json$::jsonb),
  ('es', 'docs.gatewayProviders.summary', $json$"Dos gateways de API dan a Jev acceso a muchos modelos con una sola dirección y una sola clave. Responden con texto: nunca editan archivos ni ejecutan comandos, así que Jev los usa para preguntas, análisis, revisión y planificación. Con Aprobar servidores MCP activado en su pestaña, JayV también les ofrece las herramientas de tus servidores MCP y ejecuta las llamadas que pidan."$json$::jsonb),
  ('zh-CN', 'docs.gatewayProviders.summary', $json$"两个 API 网关让 Jev 通过一个地址和一个密钥使用众多模型。它们以文本作答：从不编辑文件或运行命令，因此 Jev 用它们处理提问、分析、审查和规划。在它们的标签页中开启“批准 MCP 服务器”后，JayV 还会向它们提供你的 MCP 服务器的工具，并执行它们请求的调用。"$json$::jsonb),
  ('hi', 'docs.gatewayProviders.summary', $json$"दो API गेटवे Jev को एक पते और एक कुंजी से कई मॉडलों तक पहुँच देते हैं। वे टेक्स्ट में जवाब देते हैं: कभी फ़ाइलें नहीं बदलते और कमांड नहीं चलाते, इसलिए Jev उन्हें प्रश्नों, विश्लेषण, समीक्षा और योजना के लिए इस्तेमाल करता है। उनके टैब में MCP सर्वर स्वीकृत करें चालू होने पर JayV उन्हें आपके MCP सर्वरों के टूल भी देता है और उनके माँगे कॉल चलाता है।"$json$::jsonb),
  ('ar', 'docs.gatewayProviders.summary', $json$"تمنح بوابتا API الجهاز Jev وصولًا إلى نماذج كثيرة بعنوان واحد ومفتاح واحد. تجيبان بالنص: لا تعدّلان الملفات ولا تشغّلان الأوامر، لذلك يستخدمهما Jev للأسئلة والتحليل والمراجعة والتخطيط. وعند تفعيل الموافقة على خوادم MCP في تبويبهما، يعرض JayV عليهما أيضًا أدوات خوادم MCP لديك وينفّذ الاستدعاءات التي تطلبانها."$json$::jsonb),
  ('fr', 'docs.gatewayProviders.summary', $json$"Deux passerelles d’API donnent à Jev accès à de nombreux modèles par une seule adresse et une seule clé. Elles répondent par du texte : elles ne modifient jamais de fichiers et n’exécutent jamais de commandes, Jev les utilise donc pour les questions, l’analyse, la revue et la planification. Avec Approuver les serveurs MCP activé dans leur onglet, JayV leur propose aussi les outils de vos serveurs MCP et exécute les appels qu’elles demandent."$json$::jsonb),
  ('ru', 'docs.gatewayProviders.summary', $json$"Два API-шлюза дают Jev доступ ко многим моделям через один адрес и один ключ. Они отвечают текстом: никогда не редактируют файлы и не запускают команды, поэтому Jev использует их для вопросов, анализа, ревью и планирования. Если на их вкладке включено «Одобрять серверы MCP», JayV также предлагает им инструменты ваших серверов MCP и выполняет запрошенные ими вызовы."$json$::jsonb),
  ('ja', 'docs.gatewayProviders.summary', $json$"2つの API ゲートウェイにより、Jev は1つのアドレスと1つのキーで多数のモデルを使えます。テキストで応答し、ファイルの編集やコマンドの実行は行わないため、Jev は質問、分析、レビュー、計画に使います。それぞれのタブで「MCP サーバーを承認」をオンにすると、JayV は MCP サーバーのツールも提示し、求められた呼び出しを実行します。"$json$::jsonb),
  ('de', 'docs.gatewayProviders.summary', $json$"Zwei API-Gateways geben Jev über eine Adresse und einen Schlüssel Zugriff auf viele Modelle. Sie antworten mit Text: Sie bearbeiten nie Dateien und führen nie Befehle aus, daher nutzt Jev sie für Fragen, Analyse, Review und Planung. Ist „MCP-Server freigeben“ in ihrem Tab eingeschaltet, bietet JayV ihnen zusätzlich die Werkzeuge Ihrer MCP-Server an und führt die angeforderten Aufrufe aus."$json$::jsonb),
  ('pt-BR', 'mechanism.mcp', $json$"Aprovar servidores MCP"$json$::jsonb),
  ('en', 'mechanism.mcp', $json$"Approve MCP servers"$json$::jsonb),
  ('es', 'mechanism.mcp', $json$"Aprobar servidores MCP"$json$::jsonb),
  ('zh-CN', 'mechanism.mcp', $json$"批准 MCP 服务器"$json$::jsonb),
  ('hi', 'mechanism.mcp', $json$"MCP सर्वर स्वीकृत करें"$json$::jsonb),
  ('ar', 'mechanism.mcp', $json$"الموافقة على خوادم MCP"$json$::jsonb),
  ('fr', 'mechanism.mcp', $json$"Approuver les serveurs MCP"$json$::jsonb),
  ('ru', 'mechanism.mcp', $json$"Одобрять серверы MCP"$json$::jsonb),
  ('ja', 'mechanism.mcp', $json$"MCP サーバーを承認"$json$::jsonb),
  ('de', 'mechanism.mcp', $json$"MCP-Server freigeben"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.mcpAllAgents.title', $json$"Servidores MCP para todos os agentes"$json$::jsonb),
  ('en', 'whatsNew.item.mcpAllAgents.title', $json$"MCP servers for every agent"$json$::jsonb),
  ('es', 'whatsNew.item.mcpAllAgents.title', $json$"Servidores MCP para todos los agentes"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.mcpAllAgents.title', $json$"MCP 服务器适用于所有代理"$json$::jsonb),
  ('hi', 'whatsNew.item.mcpAllAgents.title', $json$"सभी एजेंटों के लिए MCP सर्वर"$json$::jsonb),
  ('ar', 'whatsNew.item.mcpAllAgents.title', $json$"خوادم MCP لكل الوكلاء"$json$::jsonb),
  ('fr', 'whatsNew.item.mcpAllAgents.title', $json$"Des serveurs MCP pour tous les agents"$json$::jsonb),
  ('ru', 'whatsNew.item.mcpAllAgents.title', $json$"Серверы MCP для всех агентов"$json$::jsonb),
  ('ja', 'whatsNew.item.mcpAllAgents.title', $json$"すべてのエージェントで MCP サーバー"$json$::jsonb),
  ('de', 'whatsNew.item.mcpAllAgents.title', $json$"MCP-Server für alle Agenten"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.mcpAllAgents.detail', $json$"Todo servidor de Configurações › MCP agora chega ao Claude Code, Codex, Copilot, Cursor, Kilo Code, OpenRouter e LiteLLM, desde que “Aprovar servidores MCP” esteja ligado na aba do agente: o mesmo interruptor para todos, desligado por padrão. OpenRouter e LiteLLM chamam as ferramentas pelo próprio JayV. O Ctrl+K tem um comando para virar o interruptor de cada agente."$json$::jsonb),
  ('en', 'whatsNew.item.mcpAllAgents.detail', $json$"Every server of Settings › MCP now reaches Claude Code, Codex, Copilot, Cursor, Kilo Code, OpenRouter and LiteLLM, as long as “Approve MCP servers” is on in that agent’s tab: the same switch for all of them, off by default. OpenRouter and LiteLLM call the tools through JayV itself. Ctrl+K has a command to flip the switch per agent."$json$::jsonb),
  ('es', 'whatsNew.item.mcpAllAgents.detail', $json$"Todos los servidores de Configuración › MCP llegan ahora a Claude Code, Codex, Copilot, Cursor, Kilo Code, OpenRouter y LiteLLM, siempre que «Aprobar servidores MCP» esté activado en la pestaña del agente: el mismo interruptor para todos, desactivado por defecto. OpenRouter y LiteLLM llaman a las herramientas a través del propio JayV. Ctrl+K tiene un comando para cambiar el interruptor de cada agente."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.mcpAllAgents.detail', $json$"“设置 › MCP”中的每个服务器现在都能送达 Claude Code、Codex、Copilot、Cursor、Kilo Code、OpenRouter 和 LiteLLM，前提是该代理标签页中的“批准 MCP 服务器”已开启：所有代理使用同一个开关，默认关闭。OpenRouter 和 LiteLLM 通过 JayV 自身调用工具。Ctrl+K 中有可切换每个代理开关的命令。"$json$::jsonb),
  ('hi', 'whatsNew.item.mcpAllAgents.detail', $json$"सेटिंग › MCP का हर सर्वर अब Claude Code, Codex, Copilot, Cursor, Kilo Code, OpenRouter और LiteLLM तक पहुँचता है, बशर्ते उस एजेंट के टैब में “MCP सर्वर स्वीकृत करें” चालू हो: सबके लिए वही स्विच, डिफ़ॉल्ट रूप से बंद। OpenRouter और LiteLLM टूल JayV के ज़रिए कॉल करते हैं। Ctrl+K में हर एजेंट का स्विच पलटने की कमांड है।"$json$::jsonb),
  ('ar', 'whatsNew.item.mcpAllAgents.detail', $json$"أصبح كل خادم في الإعدادات › MCP يصل إلى Claude Code وCodex وCopilot وCursor وKilo Code وOpenRouter وLiteLLM، ما دام «الموافقة على خوادم MCP» مفعّلًا في تبويب الوكيل: المفتاح نفسه للجميع، ومتوقف افتراضيًا. يستدعي OpenRouter وLiteLLM الأدوات عبر JayV نفسه. في Ctrl+K أمر لتبديل المفتاح لكل وكيل."$json$::jsonb),
  ('fr', 'whatsNew.item.mcpAllAgents.detail', $json$"Chaque serveur de Paramètres › MCP parvient désormais à Claude Code, Codex, Copilot, Cursor, Kilo Code, OpenRouter et LiteLLM, tant que « Approuver les serveurs MCP » est activé dans l’onglet de l’agent : le même interrupteur pour tous, désactivé par défaut. OpenRouter et LiteLLM appellent les outils par JayV lui-même. Ctrl+K propose une commande pour basculer l’interrupteur de chaque agent."$json$::jsonb),
  ('ru', 'whatsNew.item.mcpAllAgents.detail', $json$"Каждый сервер из «Настройки › MCP» теперь доступен Claude Code, Codex, Copilot, Cursor, Kilo Code, OpenRouter и LiteLLM, если на вкладке агента включено «Одобрять серверы MCP»: один и тот же переключатель для всех, по умолчанию выключен. OpenRouter и LiteLLM вызывают инструменты через сам JayV. В Ctrl+K есть команда, переключающая его для каждого агента."$json$::jsonb),
  ('ja', 'whatsNew.item.mcpAllAgents.detail', $json$"設定 › MCP のすべてのサーバーが、エージェントのタブで「MCP サーバーを承認」がオンであれば、Claude Code、Codex、Copilot、Cursor、Kilo Code、OpenRouter、LiteLLM に届くようになりました。すべてのエージェントで同じスイッチで、初期値はオフです。OpenRouter と LiteLLM は JayV 自身を通じてツールを呼び出します。Ctrl+K にはエージェントごとにスイッチを切り替えるコマンドがあります。"$json$::jsonb),
  ('de', 'whatsNew.item.mcpAllAgents.detail', $json$"Jeder Server aus Einstellungen › MCP erreicht jetzt Claude Code, Codex, Copilot, Cursor, Kilo Code, OpenRouter und LiteLLM, sofern „MCP-Server freigeben“ im Tab des Agenten eingeschaltet ist: derselbe Schalter für alle, standardmäßig aus. OpenRouter und LiteLLM rufen die Werkzeuge über JayV selbst auf. In Strg+K gibt es einen Befehl, der den Schalter je Agent umlegt."$json$::jsonb),
  ('en', 'site.org.mcp.field.agents.hint', $json$"With none checked, it applies to every agent. Each member’s app hands it over only to the agents that have “Approve MCP servers” on."$json$::jsonb),
  ('pt-BR', 'site.org.mcp.field.agents.hint', $json$"Sem marcar nenhum, vale para todos os agentes. O app de cada membro só o entrega aos agentes com “Aprovar servidores MCP” ligado."$json$::jsonb),
  ('es', 'site.org.mcp.field.agents.hint', $json$"Sin marcar ninguno, vale para todos los agentes. La app de cada miembro solo lo entrega a los agentes con «Aprobar servidores MCP» activado."$json$::jsonb),
  ('zh-CN', 'site.org.mcp.field.agents.hint', $json$"不勾选任何一项时，适用于所有代理。每位成员的应用只会把它交给已开启“批准 MCP 服务器”的代理。"$json$::jsonb),
  ('hi', 'site.org.mcp.field.agents.hint', $json$"कुछ भी न चुनने पर यह सभी एजेंटों पर लागू होता है। हर सदस्य का ऐप इसे सिर्फ़ उन एजेंटों को देता है जिनमें “MCP सर्वर स्वीकृत करें” चालू है।"$json$::jsonb),
  ('ar', 'site.org.mcp.field.agents.hint', $json$"عند عدم تحديد أي خيار، ينطبق على كل الوكلاء. يسلّمه تطبيق كل عضو فقط إلى الوكلاء المفعّل لديهم «الموافقة على خوادم MCP»."$json$::jsonb),
  ('fr', 'site.org.mcp.field.agents.hint', $json$"Sans aucune case cochée, il s’applique à tous les agents. L’application de chaque membre ne le remet qu’aux agents dont « Approuver les serveurs MCP » est activé."$json$::jsonb),
  ('ru', 'site.org.mcp.field.agents.hint', $json$"Если ничего не отмечено, действует для всех агентов. Приложение каждого участника передаёт его только агентам с включённым «Одобрять серверы MCP»."$json$::jsonb),
  ('ja', 'site.org.mcp.field.agents.hint', $json$"何も選ばない場合はすべてのエージェントが対象です。各メンバーのアプリは、「MCP サーバーを承認」がオンのエージェントにだけ渡します。"$json$::jsonb),
  ('de', 'site.org.mcp.field.agents.hint', $json$"Ist nichts angehakt, gilt er für alle Agenten. Die App jedes Mitglieds übergibt ihn nur an Agenten mit eingeschaltetem „MCP-Server freigeben“."$json$::jsonb)
